use vstd::prelude::*;

verus! {

spec fn all_less_than(n: int, a: Seq<int>) -> bool {
    forall|i: int| 0 <= i < a.len() ==> a[i] < n
}

fn is_greater(n: i32, a: &Vec<i32>) -> (res: bool)
    requires
        a.len() > 0,
    ensures
        res == all_less_than(n as int, a@.map_values(|x: i32| x as int)),
{
    // Assumption: a is non-empty (length > 0)
    for &x in a.iter()
        invariant
            a.len() > 0,
            // All elements seen so far are < n
            forall|i: int| 0 <= i < a@.len() - a.iter().len() ==> a@[i] < n as int,
    {
        if n <= x {
            return false;
        }
        // After passing the check, we know the current element is < n
        assert(x as int < n as int);
    }
    true
}

} // verus!

